  return [true, "command argv matched an approved prefix in the non-executing review"];
}

function decision(
  request: ActionRequest,
  verdict: Verdict,
  rule: string,
  reason: string,
  normalizedTarget: string | null = null,
  normalizedOrigin: string | null = null,
): ReviewDecision {
